const Parser = require('rss-parser');
const parser = new Parser();

const rssContent = items[0].json.data;
const feed = await parser.parseString(rssContent);

const events = feed.items.map(item => ({
  title: item.title,
  description: item.contentSnippet || item.description,
  startAt: item.pubDate || item.isoDate,
  url: item.link,
  sourceUid: item.guid || item.link,
  sourceKind: 'RSS',
  category: item.categories || [],
}));

return events.map(event => ({ json: event }));

// Extract additional data from description
const item = $json;

// Try to extract date from description
const dateRegex = /(\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4})/;
const dateMatch = item.description?.match(dateRegex);

if (dateMatch && !item.startAt) {
  item.startAt = new Date(dateMatch[0]).toISOString();
}

// Try to extract city
const cityRegex = /à ([A-ZÀ-Ÿ][a-zà-ÿ\-]+(?:\s[A-ZÀ-Ÿ][a-zà-ÿ\-]+)*)/;
const cityMatch = item.description?.match(cityRegex);

if (cityMatch) {
  item.city = cityMatch[1];
}

// Try to extract venue
const venueRegex = /lieu[\s:]+([^\.,]+)/i;
const venueMatch = item.description?.match(venueRegex);

if (venueMatch) {
  item.venueName = venueMatch[1].trim();
}

// Try to extract price
const priceRegex = /(\d+(?:[,\.]\d{2})?)\s*€/;
const priceMatch = item.description?.match(priceRegex);

if (priceMatch) {
  item.priceMin = parseFloat(priceMatch[1].replace(',', '.'));
}

// Check for free event
if (item.description?.match(/gratuit|entrée libre/i)) {
  item.priceMin = 0;
}

return { json: item };
